function mergeArtifactStates(
  previous: readonly EpisodeArtifactState[] | undefined,
  current: readonly EpisodeArtifactState[],
  changedPaths: readonly string[],
): readonly EpisodeArtifactState[] {
  if (previous === undefined || previous.length === 0) return current;
  const changed = new Set(changedPaths);
  const priorByPath = new Map(previous.map((state) => [state.path, state]));
  return Object.freeze(
    current.map((state) => {
      if (changed.has(state.path)) return state;
      const prior = priorByPath.get(state.path);
      if (prior === undefined) return state;
      if (
        prior.digest !== state.digest ||
        prior.present !== state.present ||
        prior.tracked !== state.tracked ||
        prior.committed !== state.committed
      ) {
        return state;
      }
      // Older guard records wrote a non-canonical detail. Carrying it forward would keep the
      // delivery invisible to a canonical-detail consumer; normalize it without changing the facts.
      const detail = prior.detail.includes("direct-delivery guard provenance refresh")
        ? "committed at HEAD"
        : prior.detail;
      return Object.freeze({ ...prior, detail });
    }),
  );
}

/**
 * Recover the principal's statement from an older refresh that appended a guard suffix. The guard
 * added that suffix itself; removing it restores the judgement text without inventing anything. A
 * statement that never carried the exact legacy suffix is returned unchanged.
 */
function principalStatement(statement: string): string {
  return statement
    .replace(/\s*Direct-delivery guard refreshed provenance at [0-9a-f]{12};[\s\S]*$/u, "")
    .trim();
}

